44	     * 获取帖子详情
45	     * GET /api/posts/{id}
46	     */
47	    @GetMapping("/{id}")
48	    public ResponseEntity<PostResponse> getPostById(@PathVariable Long id) {
49	        PostResponse post = postService.getPostById(id);
50	        return ResponseEntity.ok(post);
