53	    /**
54	     * 更新帖子
55	     * PUT /api/posts/{id}
56	     */
57	    @PutMapping("/{id}")
58	    public ResponseEntity<ApiResponse<PostResponse>> updatePost(
59	            @PathVariable Long id,
60	            @Valid @RequestBody UpdatePostRequest request
