13	
14	import java.util.List;
15	
16	/**
17	 * 评论控制器
18	 * 处理评论相关的请求
19	 */
20	@RestController
21	@RequestMapping("/api")
22	public class CommentController {
23	
24	    private final CommentService commentService;
25	
26	    public CommentController(CommentService commentService) {
27	        this.commentService = commentService;
28	    }
29	
30	    /**
31	     * 创建评论
32	     * POST /api/posts/{postId}/comments
33	     */
34	    @PostMapping("/posts/{postId}/comments")
35	    public ResponseEntity<ApiResponse<CommentResponse>> createComment(
36	            @PathVariable Long postId,
37	            @Valid @RequestBody CreateCommentRequest request
38	    ) {
39	        String username = getCurrentUsername();
40	        CommentResponse comment = commentService.createComment(username, postId, request);
41	        return ResponseEntity.ok(ApiResponse.success("评论创建成功", comment));
42	    }
43	
44	    /**
45	     * 回复评论
46	     * POST /api/comments/{id}/reply
47	     */
48	    @PostMapping("/comments/{id}/reply")
49	    public ResponseEntity<ApiResponse<CommentResponse>> replyToComment(
50	            @PathVariable Long id,
51	            @Valid @RequestBody CreateCommentRequest request
52	    ) {
53	        String username = getCurrentUsername();
54	        CommentResponse comment = commentService.replyToComment(username, id, request);
55	        return ResponseEntity.ok(ApiResponse.success("回复成功", comment));
56	    }
57	
58	    /**
59	     * 删除评论
60	     * DELETE /api/comments/{id}
61	     */
62	    @DeleteMapping("/comments/{id}")
63	    public ResponseEntity<ApiResponse<Void>> deleteComment(@PathVariable Long id) {
64	        String username = getCurrentUsername();
65	        commentService.deleteComment(username, id);
66	        return ResponseEntity.ok(ApiResponse.success("评论删除成功"));
67	    }
68	
