70	     * 获取帖子的所有评论
71	     * GET /api/posts/{postId}/comments
72	     */
73	    @GetMapping("/posts/{postId}/comments")
74	    public ResponseEntity<List<CommentResponse>> getCommentsByPostId(@PathVariable Long postId) {
75	        List<CommentResponse> comments = commentService.getCommentsByPostId(postId);
76	        return ResponseEntity.ok(comments);
77	    }
