859	+    /**
860	+     * 创建举报
861	+     *
862	+     * @param username    举报人用户名
863	+     * @param targetId    被举报目标 ID
864	+     * @param targetType  目标类型 (POST / COMMENT)
865	+     * @param reason      举报原因
866	+     * @param description 补充描述（拼接到 reason 中）
867	+     * @return 保存后的 Report 实体
868	+     */
869	+    @Transactional
870	+    public Report createReport(String username, Long targetId, String targetType, String reason, String description) {
871	+        User user = userRepository.findByUsername(username)
872	+                .orElseThrow(() -> new ResourceNotFoundException("用户不存在"));
873	+
874	+        Report.TargetType type = Report.TargetType.valueOf(targetType.toUpperCase());
875	+
876	+        // 将 description 附加到 reason 后面，避免修改实体
877	+        String fullReason = reason;
878	+        if (description != null && !description.trim().isEmpty()) {
879	+            fullReason = reason + " | " + description;
880	+        }
881	+
882	+        Report report = new Report(user.getId(), type, targetId, fullReason);
883	+        report = reportRepository.save(report);
884	+
885	+        logger.info("举报创建成功: id={}, reporter={}, targetType={}, targetId={}",
886	+                report.getId(), username, targetType, targetId);
887	+
888	+        return report;
889	+    }
