package com.cc91.util;

import org.springframework.web.util.HtmlUtils;

/**
 * HTML 净化工具类，防止存储型 XSS 攻击
 */
public class HtmlSanitizer {

    private HtmlSanitizer() {
        // 工具类不允许实例化
    }

    /**
     * 转义 HTML 特殊字符，防止存储型 XSS
     */
    public static String escape(String input) {
        if (input == null) return null;
        return HtmlUtils.htmlEscape(input, "UTF-8");
    }

    /**
     * 对内容进行基本净化 -- 允许部分安全的 HTML 标签（如帖子内容中的格式化标签）
     * 但移除 script、iframe、onXXX 等危险内容
     */
    public static String sanitizeContent(String content) {
        if (content == null) return null;
        // 移除 script 标签
        String sanitized = content.replaceAll("(?i)<script[^>]*>.*?</script>", "");
        // 移除 onXXX 事件属性
        sanitized = sanitized.replaceAll("(?i)\\s+on\\w+\\s*=\\s*[\"'][^\"']*[\"']", "");
        // 移除 iframe、object、embed 标签
        sanitized = sanitized.replaceAll("(?i)</?(iframe|object|embed|form|input)[^>]*>", "");
        // 移除 javascript: 协议
        sanitized = sanitized.replaceAll("(?i)javascript:", "");
        return sanitized;
    }
}

package com.cc91.controller;

import com.cc91.dto.AdminCommentDTO;
import com.cc91.dto.ApiResponse;
import com.cc91.dto.PostResponse;
import com.cc91.dto.UpdatePostStatusRequest;
import com.cc91.entity.Comment;
import com.cc91.entity.Post;
import com.cc91.exception.ResourceNotFoundException;
import com.cc91.repository.CommentRepository;
import com.cc91.repository.PostRepository;
import com.cc91.service.NotificationService;
import com.cc91.service.PostService;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.data.domain.Page;
import org.springframework.data.domain.PageRequest;
import org.springframework.http.ResponseEntity;

import java.util.List;
import java.util.stream.Collectors;
import org.springframework.security.access.prepost.PreAuthorize;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;

/**
 * 管理员 - 内容审核控制器
 */
@RestController
@RequestMapping("/api/admin")
@PreAuthorize("hasRole('ADMIN')")
public class AdminContentController {

    private static final Logger logger = LoggerFactory.getLogger(AdminContentController.class);

    private final PostRepository postRepository;
    private final CommentRepository commentRepository;
    private final PostService postService;
    private final NotificationService notificationService;

    public AdminContentController(PostRepository postRepository,
                                  CommentRepository commentRepository,
                                  PostService postService,
                                  NotificationService notificationService) {
        this.postRepository = postRepository;
        this.commentRepository = commentRepository;
        this.postService = postService;
        this.notificationService = notificationService;
    }

    /**
     * 查看所有帖子（按状态筛选）
     * GET /api/admin/posts?status=PUBLISHED&page=0&size=20
     */
    @GetMapping("/posts")
    public ResponseEntity<Page<PostResponse>> getPostsByStatus(
            @RequestParam(required = false) String status,
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size
    ) {
        Page<PostResponse> response = postService.getPostList(page, size, status);
        return ResponseEntity.ok(response);
    }

    /**
     * 修改帖子状态
     * PUT /api/admin/posts/{id}/status
     */
    @PutMapping("/posts/{id}/status")
    public ResponseEntity<ApiResponse<Void>> updatePostStatus(
            @PathVariable Long id,
            @RequestBody UpdatePostStatusRequest request
    ) {
        Post post = postRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));

        post.setStatus(request.getStatus());
        postRepository.save(post);

        // 通知帖子作者状态变更
        notificationService.createNotification(
                post.getAuthorId(), "POST_STATUS", "帖子状态变更",
                "您的帖子「" + post.getTitle() + "」状态已变更为：" + request.getStatus(),
                post.getId()
        );

        logger.info("管理员修改帖子状态: id={}, status={}, 已通知作者 authorId={}",
                id, request.getStatus(), post.getAuthorId());

        return ResponseEntity.ok(ApiResponse.success("帖子状态已更新"));
    }

    /**
     * 强制删除帖子
     * DELETE /api/admin/posts/{id}
     */
    @DeleteMapping("/posts/{id}")
    public ResponseEntity<ApiResponse<Void>> forceDeletePost(@PathVariable Long id) {
        Post post = postRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("帖子不存在"));

        postRepository.delete(post);

        logger.info("管理员强制删除帖子: id={}", id);

        return ResponseEntity.ok(ApiResponse.success("帖子已删除"));
    }

    /**
     * 查看所有评论（按时间倒序，分页）
     * GET /api/admin/comments?page=0&size=20
     */
    @GetMapping("/comments")
    @Transactional(readOnly = true)
    public ResponseEntity<Page<AdminCommentDTO>> getAllComments(
            @RequestParam(defaultValue = "0") int page,
            @RequestParam(defaultValue = "20") int size
    ) {
        Page<Comment> comments = commentRepository.findPageWithPostAndAuthorByOrderByCreatedAtDesc(PageRequest.of(page, size));
        Page<AdminCommentDTO> dtos = comments.map(c -> {
            String postTitle = c.getPost() != null ? c.getPost().getTitle() : "已删除";
            return new AdminCommentDTO(
                    c.getId(), c.getPostId(), postTitle,
                    c.getAuthorId(),
                    c.getAuthor() != null ? c.getAuthor().getUsername() : "已删除",
                    c.getContent(), c.getParentId(),
                    c.getStatus(), c.getCreatedAt()
            );
        });
        return ResponseEntity.ok(dtos);
    }

    /**
     * 强制删除评论
     * DELETE /api/admin/comments/{id}
     */
    @DeleteMapping("/comments/{id}")
    public ResponseEntity<ApiResponse<Void>> forceDeleteComment(@PathVariable Long id) {
        com.cc91.entity.Comment comment = commentRepository.findById(id)
                .orElseThrow(() -> new ResourceNotFoundException("评论不存在"));

        commentRepository.delete(comment);

        logger.info("管理员强制删除评论: id={}", id);

        return ResponseEntity.ok(ApiResponse.success("评论已删除"));
    }
}

